import{_ as e,o as a,c as n,a4 as t}from"./chunks/framework.BMj-uaUw.js";const g=JSON.parse('{"title":"单元 2 · AI 协作：依赖与版本，别交给 AI 记","description":"","frontmatter":{},"headers":[{"level":2,"title":"这一章哪些活能交给 AI","slug":"这一章哪些活能交给-ai","link":"#这一章哪些活能交给-ai","children":[]},{"level":2,"title":"提示词怎么写","slug":"提示词怎么写","link":"#提示词怎么写","children":[{"level":3,"title":"1. 让它解释一条依赖报错","slug":"_1-让它解释一条依赖报错","link":"#_1-让它解释一条依赖报错","children":[]},{"level":3,"title":"2. 让它审 package.json，并标出它不确定的地方","slug":"_2-让它审-package-json-并标出它不确定的地方","link":"#_2-让它审-package-json-并标出它不确定的地方","children":[]},{"level":3,"title":"3. 让它审 vite.config.js，每条配置都要给验证办法","slug":"_3-让它审-vite-config-js-每条配置都要给验证办法","link":"#_3-让它审-vite-config-js-每条配置都要给验证办法","children":[]}]},{"level":2,"title":"AI 在这一章容易错什么","slug":"ai-在这一章容易错什么","link":"#ai-在这一章容易错什么","children":[{"level":3,"title":"版本号凭记忆写","slug":"版本号凭记忆写","link":"#版本号凭记忆写","children":[]},{"level":3,"title":"报一个并不存在的包名","slug":"报一个并不存在的包名","link":"#报一个并不存在的包名","children":[]},{"level":3,"title":"建议你删掉锁文件","slug":"建议你删掉锁文件","link":"#建议你删掉锁文件","children":[]},{"level":3,"title":"把 dependencies 和 devDependencies 放反","slug":"把-dependencies-和-devdependencies-放反","link":"#把-dependencies-和-devdependencies-放反","children":[]}]},{"level":2,"title":"怎么验收 AI 的产出","slug":"怎么验收-ai-的产出","link":"#怎么验收-ai-的产出","children":[]},{"level":2,"title":"练习","slug":"练习","link":"#练习","children":[{"level":3,"title":"用 AI 审一遍自己的 package.json","slug":"用-ai-审一遍自己的-package-json","link":"#用-ai-审一遍自己的-package-json","children":[]}]}],"relativePath":"unit02/ai-collaboration.md","filePath":"unit02/ai-collaboration.md","lastUpdated":1789356894000}'),i={name:"unit02/ai-collaboration.md"};function o(p,s,l,d,c,r){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="单元-2-·-ai-协作-依赖与版本-别交给-ai-记" tabindex="-1">单元 2 · AI 协作：依赖与版本，别交给 AI 记 <a class="header-anchor" href="#单元-2-·-ai-协作-依赖与版本-别交给-ai-记" aria-label="Permalink to &quot;单元 2 · AI 协作：依赖与版本，别交给 AI 记&quot;">​</a></h1><p>这一章的内容有个共同点：<strong>全是事实型知识。</strong> Node 有哪些 LTS 版本、<code>engines</code> 字段怎么写、<code>^</code> 和 <code>~</code> 差别在哪、镜像源地址是什么、某个包该放 <code>dependencies</code> 还是 <code>devDependencies</code> —— 这些问题的答案不是&quot;想&quot;出来的，是&quot;查&quot;出来的。</p><p>而 AI 恰恰不擅长这一类知识。它可以跟你讲清 <code>package.json</code> 里每个字段的设计意图，但它给你写出来的版本号，很可能在 npm 上根本不存在，或者早就过了维护期。</p><p>这一章的两个产出，依赖排查单和 <code>vite.config.js</code>，都属于&quot;照抄就会踩坑&quot;的东西。所以这一节的用法和上一章不同：<strong>让 AI 讲清原理，让官方仓库定事实。</strong></p><h2 id="这一章哪些活能交给-ai" tabindex="-1">这一章哪些活能交给 AI <a class="header-anchor" href="#这一章哪些活能交给-ai" aria-label="Permalink to &quot;这一章哪些活能交给 AI&quot;">​</a></h2><p>判断标准：<strong>能帮你把看不懂的东西看懂，这类活可以交；凡是涉及具体版本号、包名、命令取值的，必须自己查一遍。</strong></p><table tabindex="0"><thead><tr><th>任务</th><th>能交给 AI 吗</th><th>为什么</th></tr></thead><tbody><tr><td>解释一条依赖报错在说什么</td><td>可以</td><td>报错原文是给包管理器看的，它翻译得比你好</td></tr><tr><td>讲清 <code>package.json</code> 某个字段的作用</td><td>可以</td><td>它见过大量真实项目里的用法</td></tr><tr><td>给一份&quot;安装失败的可能原因&quot;清单</td><td>可以</td><td>有价值的是排序，不是结论</td></tr><tr><td>帮你把 <code>vite.config.js</code> 翻译成人话</td><td>可以</td><td>但每条配置都要你跑一遍才算数</td></tr><tr><td>对比两个依赖的取舍</td><td>可以</td><td>当起点用，最终由你的项目决定</td></tr><tr><td>写出具体的版本号</td><td><strong>不能直接信</strong></td><td>它的知识有截止时间，前端工具以月为单位迭代</td></tr><tr><td>报一个包名让你装</td><td><strong>不能直接信</strong></td><td>见下面的&quot;幻觉依赖&quot;</td></tr><tr><td>决定删不删锁文件</td><td><strong>不行</strong></td><td>这是团队协作层面的决定</td></tr></tbody></table><p>中间那两行是这一章的重点。<strong>版本号和包名是最容易被照抄进项目、又最容易被发现是错的两类信息。</strong></p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><h3 id="_1-让它解释一条依赖报错" tabindex="-1">1. 让它解释一条依赖报错 <a class="header-anchor" href="#_1-让它解释一条依赖报错" aria-label="Permalink to &quot;1. 让它解释一条依赖报错&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在 pnpm install 时遇到这个报错：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[完整粘贴，从 ERR_ 开头那一行到最后一行]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>环境：Node v24.9.0，pnpm 12.4.1，Windows 11。</span></span>
<span class="line"><span>在此之前我刚把 registry 换成了 [镜像地址]。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按这个顺序回答：</span></span>
<span class="line"><span>1. 这条报错在描述哪一层出了问题（网络 / 镜像 / 版本 / 权限 / 缓存 / 锁文件）</span></span>
<span class="line"><span>2. 给出排查顺序，每步一条能直接跑的命令，以及&quot;看到什么说明是这一层&quot;</span></span>
<span class="line"><span>3. 你确定的地方直接说结论，不确定的地方明确说不确定</span></span></code></pre></div><p><strong>为什么这么写</strong>：第 1 点把问题限定在&quot;哪一层&quot;，正好对上 <a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2 的排查顺序</a>。第 2 点要求&quot;每步给出预期现象&quot;，因为依赖排查最耗时间的不是不知道原因，是不知道跑完这条命令该看到什么。最后一句让它敢说&quot;不确定&quot; —— 排查过程中，一个诚实的&quot;我不确定&quot;比一个笃定的错误方向省时间得多。</p><h3 id="_2-让它审-package-json-并标出它不确定的地方" tabindex="-1">2. 让它审 <code>package.json</code>，并标出它不确定的地方 <a class="header-anchor" href="#_2-让它审-package-json-并标出它不确定的地方" aria-label="Permalink to &quot;2. 让它审 \`package.json\`，并标出它不确定的地方&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我的 package.json：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴完整内容]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请逐个字段解释它在这里的作用，用表格：字段 / 作用 / 取值范围 / 我这个值合不合适。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>另外单独列一节“我不确定的地方”：凡是涉及具体版本号是否存在、</span></span>
<span class="line"><span>某个包该放 dependencies 还是 devDependencies、某个字段的默认值，</span></span>
<span class="line"><span>如果你不能确定，直接写出来，不要给一个看起来合理的答案。</span></span></code></pre></div><p><strong>为什么这么写</strong>：一次问&quot;这个文件有问题吗&quot;，它多半回&quot;整体看起来合理&quot;。拆成逐字段，它才必须给出具体判断，你才好逐条核实。后半段那句是关键 —— 明确告诉它&quot;不确定可以写出来&quot;，能挡掉相当一部分编造。你拿到的&quot;不确定清单&quot;就是你的核实待办。</p><h3 id="_3-让它审-vite-config-js-每条配置都要给验证办法" tabindex="-1">3. 让它审 <code>vite.config.js</code>，每条配置都要给验证办法 <a class="header-anchor" href="#_3-让它审-vite-config-js-每条配置都要给验证办法" aria-label="Permalink to &quot;3. 让它审 \`vite.config.js\`，每条配置都要给验证办法&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我的 vite.config.js：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴完整内容]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请回答三件事：</span></span>
<span class="line"><span>1. 每条配置解决什么问题，用一句话</span></span>
<span class="line"><span>2. 每条配置我怎么确认它真的生效了，给一条能直接跑的命令或一个可观察的现象</span></span>
<span class="line"><span>3. 有哪些配置是我写了但实际没起作用的</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要评价&quot;配置是否规范&quot;，只回答&quot;有没有生效&quot;。</span></span></code></pre></div><p><strong>为什么这么写</strong>：配置文件最麻烦的地方是<strong>写错了不报错</strong>。别名写错一个路径，构建时才发现；代理配错端口，请求静默 404。要求&quot;每条给验证办法&quot;，就把一份静态配置变成了一份可执行的检查清单。最后那句是在堵它用&quot;配置规范，符合最佳实践&quot;这类话敷衍过去。</p><h2 id="ai-在这一章容易错什么" tabindex="-1">AI 在这一章容易错什么 <a class="header-anchor" href="#ai-在这一章容易错什么" aria-label="Permalink to &quot;AI 在这一章容易错什么&quot;">​</a></h2><h3 id="版本号凭记忆写" tabindex="-1">版本号凭记忆写 <a class="header-anchor" href="#版本号凭记忆写" aria-label="Permalink to &quot;版本号凭记忆写&quot;">​</a></h3><p><strong>现象</strong>：它给你的安装命令是 <code>pnpm add vue@3.6.0</code>，或者写进 <code>package.json</code> 的依赖是 <code>&quot;vite&quot;: &quot;^7.2.0&quot;</code>。格式完全正常，但装上去不是版本不存在，就是和其他依赖对不上。</p><p><strong>原因</strong>：它的知识有截止时间。前端工具链的版本迭代以月为单位，它记住的是训练数据里的那一段，而它无法判断那一段是不是已经过期。</p><p><strong>怎么处理</strong>：<strong>版本号只从两个地方取 —— npm registry 或官方文档。</strong> 一条命令的事：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查一个包的最新版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/vue/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 包名带斜杠的，斜杠转义成 %2F</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/@vue%2Fuse%2Fcore/latest</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span></code></pre></div><p>返回 <code>{&quot;error&quot;:&quot;Not found&quot;}</code> 说明这个包不存在（不是版本不存在）。要看某个包的全部版本，去掉 <code>/latest</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org/vite</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json.tool</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&quot;latest&quot;&#39;</span></span></code></pre></div><p>本课程用到的基线版本记在<a href="/frontend-engineering-course/appendix/tools.html">工具链与版本清单</a>里，写完配置回头核一遍。</p><h3 id="报一个并不存在的包名" tabindex="-1">报一个并不存在的包名 <a class="header-anchor" href="#报一个并不存在的包名" aria-label="Permalink to &quot;报一个并不存在的包名&quot;">​</a></h3><p><strong>现象</strong>：<code>pnpm install</code> 报 <code>ERR_PNPM_FETCH_404</code> 或 <code>404 Not Found</code>。它给你的那个包名，格式、大小写、作用域都挑不出毛病。</p><p><strong>原因</strong>：这种行为叫<strong>幻觉依赖</strong>。它不是查了仓库发现没有，而是根据见过的包名按命名规则拼了一个出来 —— <code>vue-router-lite</code>、<code>@vue/sortable</code> 这类听起来很合理的名字，都是常见的编造结果。</p><p><strong>怎么处理</strong>：装之前先确认存在，别先改 <code>package.json</code> 再 <code>install</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 有版本号输出就是存在</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue-router</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 想看这个包的详细信息（作者、描述、最近发布时间）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue-router</span></span></code></pre></div><p>要判断一个包是不是&quot;真在用&quot;，可以顺带看一眼最近发布时间 —— 三年没更新的包放进新项目要谨慎。</p><h3 id="建议你删掉锁文件" tabindex="-1">建议你删掉锁文件 <a class="header-anchor" href="#建议你删掉锁文件" aria-label="Permalink to &quot;建议你删掉锁文件&quot;">​</a></h3><p><strong>现象</strong>：安装冲突时它说&quot;删除 <code>pnpm-lock.yaml</code> 再重装就能解决&quot;。</p><p><strong>原因</strong>：这是它见过最多的&quot;通用解法&quot;，但它不知道你的项目是团队协作、有 CI 流水线。</p><p><strong>怎么处理</strong>：锁文件记录了整棵依赖树的精确版本，删掉等于让每个环境重新解析一遍版本范围。<strong>&quot;我这能跑、CI 上跑不起来&quot;的问题，多半就是这么来的。</strong> 只在极少数情况才删（比如刚换了包管理器、或锁文件确实损坏）。正常的问题回到 <a href="/frontend-engineering-course/unit02/02-package-manager.html">2.2 的排查顺序</a> 逐层排除，一次只改一个变量，然后记进排查单。</p><h3 id="把-dependencies-和-devdependencies-放反" tabindex="-1">把 <code>dependencies</code> 和 <code>devDependencies</code> 放反 <a class="header-anchor" href="#把-dependencies-和-devdependencies-放反" aria-label="Permalink to &quot;把 \`dependencies\` 和 \`devDependencies\` 放反&quot;">​</a></h3><p><strong>现象</strong>：它把 <code>vite</code>、<code>eslint</code>、<code>vitest</code> 写进 <code>dependencies</code>，或者把 <code>element-plus</code> 放进 <code>devDependencies</code>。</p><p><strong>原因</strong>：它的判断依据是&quot;这个包看起来像不像开发工具&quot;，而这个词的边界很模糊 —— <code>vite</code> 算是工具，那 <code>vite</code> 的插件呢？</p><p><strong>怎么处理</strong>：判断标准只有一条 —— <strong>这个包会不会被打进最终产物。</strong> 打包工具、检查工具、测试工具、类型定义放 <code>devDependencies</code>；被页面代码 <code>import</code> 进来、运行时要用到的放 <code>dependencies</code>。拿不准就用一个动作验证：<code>pnpm build</code> 之后看产物里有没有它。</p><details class="details custom-block"><summary>还有一类错误：改 <code>type</code> 或升大版本，却不提影响面</summary><p><strong>现象</strong>：它说&quot;把 <code>&quot;type&quot;</code> 改成 <code>&quot;module&quot;</code> 就能解决&quot;，或者&quot;升级到最新大版本就好了&quot;。你照着改了，别的文件开始报错。</p><p><strong>原因</strong>：这类改动的影响面不在它拿到的上下文里。它只看到你贴的那一个文件，看不到还有哪些地方依赖了旧行为。</p><p><strong>怎么处理</strong>：凡是动到 <code>type</code>、<code>engines</code>、<code>packageManager</code> 或主版本号的建议，都先追问一句：<strong>&quot;这个改动还会影响哪些文件？&quot;</strong> 然后自己搜一遍引用位置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看还有哪些文件要求了某种模块格式</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;require(&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vite.config.js</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看有没有地方写死了 Node 版本</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;engines\\|node -v&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .github/</span></span></code></pre></div><p><code>type</code> 字段这类全局设置，改错的表现往往是<strong>一部分文件正常、一部分文件报错的语法错误</strong>，很难第一眼看出根因。所以宁可先问清影响面，也不要直接改。</p></details><h2 id="怎么验收-ai-的产出" tabindex="-1">怎么验收 AI 的产出 <a class="header-anchor" href="#怎么验收-ai-的产出" aria-label="Permalink to &quot;怎么验收 AI 的产出&quot;">​</a></h2><p>这一章的产出是配置和依赖清单，验收动作比上一章更硬 —— 大部分都能用运行结果判定。逐条过：</p><ul><li>[ ] 它给的每个版本号，都在 <code>registry.npmjs.org</code> 上查到了</li><li>[ ] 它提到的每个包名，都用 <code>npm view &lt;包名&gt; version</code> 确认过存在</li><li>[ ] 它判断的 <code>dependencies</code> / <code>devDependencies</code> 归属，你按&quot;会不会进产物&quot;复核过</li><li>[ ] 它给的每条 <code>vite.config.js</code> 配置，你都跑过 <code>pnpm dev</code> 或 <code>pnpm build</code> 确认生效</li><li>[ ] 它没有建议你删锁文件；如果有，你问清了理由并记进了排查单</li><li>[ ] 它给的镜像源地址你现在访问得通</li><li>[ ] 动到 <code>type</code>、<code>engines</code>、主版本号的建议，你搜过影响面</li><li>[ ] 改完能跑通 <code>pnpm install</code> 与 <code>pnpm build &amp;&amp; pnpm preview</code></li></ul><p>前三条对应&quot;事实对不对&quot;，中间三条对应&quot;配置真的生效了没&quot;，最后两条对应&quot;改动的影响面控制住了&quot;。<strong>这八条过完，这一章的配置就可以提交了。</strong></p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><h3 id="用-ai-审一遍自己的-package-json" tabindex="-1">用 AI 审一遍自己的 <code>package.json</code> <a class="header-anchor" href="#用-ai-审一遍自己的-package-json" aria-label="Permalink to &quot;用 AI 审一遍自己的 \`package.json\`&quot;">​</a></h3><p><strong>任务</strong>：拿第 1 周建好的练习工程，让 AI 逐个字段解释一遍，然后<strong>逐条核实它说的每一个事实</strong>，最后交一份分歧清单。</p><p><strong>要求</strong>：记录里必须包含这四项：</p><table tabindex="0"><thead><tr><th>项</th><th>要求</th></tr></thead><tbody><tr><td>字段解释</td><td>逐个字段问，把它给的解释和自己的理解对照着记</td></tr><tr><td>它标出的&quot;不确定项&quot;</td><td>完整保留，这条清单就是你的核实待办</td></tr><tr><td>你的核实动作</td><td>每个版本号怎么查的、每个包名怎么确认的，写清命令和输出</td></tr><tr><td>分歧清单</td><td>它说错的地方，写清它错在哪、正确是什么、你怎么发现的</td></tr></tbody></table><details class="details custom-block"><summary>验收标准与参考思路</summary><p><strong>为什么要&quot;逐个字段问&quot;</strong>：一次问&quot;这个文件有没有问题&quot;，它多半回&quot;整体看起来合理&quot;。把问题拆小，它才必须给出具体判断，你才抓得住漏洞。这是这一节最实用的一个技巧。</p><p><strong>思路提示</strong>：</p><ul><li>优先核三类字段：<code>engines</code>、<code>packageManager</code>、每个依赖的版本范围。这三类最容易出错，也最容易造成&quot;本地能跑、别人报错&quot;。</li><li>让它解释一遍 <code>^</code> 与 <code>~</code> 的差别，然后拿 <a href="/frontend-engineering-course/unit02/03-package-json.html">2.3 package.json 逐字段精讲</a> 里的说法对照。有分歧就以文档为准，别以它的回答为准。</li><li>如果它报出来的版本比你实际装的还新，<strong>别急着升</strong>。先确认这个版本存在，再查它有没有破坏性改动（大版本号变了通常就有）。</li><li>分歧清单是这次练习的重点。<strong>一条分歧都找不出来，通常说明你没真核</strong>，而不是说明 AI 全对。</li></ul><p><strong>不合格的写法</strong>：</p><blockquote><p>让 AI 看了一下 package.json，它说没什么问题，我就没改。</p></blockquote><p>这句话里没有任何可验证的信息：它看的哪个字段？&quot;没问题&quot;的标准是什么？有没有可能它只是没看出来？</p><p><strong>合格的写法</strong>：</p><blockquote><p>我问 AI 逐字段解释。到 <code>engines</code> 时它说写成 <code>&quot;node&quot;: &quot;&gt;=18&quot;</code> 就行。 我查了 Node 官网的版本列表，18 已经不在维护期，而本课程从第 4 周起的 Vue 项目要求 20.19 以上。 我把字段改成 <code>&quot;node&quot;: &quot;&gt;=20.19&quot;</code>，再跑一遍 <code>pnpm install</code>，没有 <code>EBADENGINE</code> 警告。 分歧点：它按&quot;能跑就行&quot;给建议，而项目还要考虑课程后续单元的要求。</p></blockquote><p>差别在于：后者把&quot;它为什么这么建议&quot;和&quot;项目实际要求是什么&quot;摆在了一起做判断。<strong>这类判断没法让 AI 替你做，因为它不知道你的项目接下来要往哪走。</strong></p></details><hr><p>上一节：<a href="/frontend-engineering-course/unit02/05-env-config.html">2.5 环境变量与常用配置</a> · 课后练习：<a href="/frontend-engineering-course/unit02/practice.html">单元 2 课后练习</a></p>`,54)])])}const u=e(i,[["render",o]]);export{g as __pageData,u as default};
